import heapq

def find_shortest_path(moves):
    n = len(moves)
    directions = {'L': (-1, 0), 'R': (1, 0), 'U': (0, -1), 'D': (0, 1)}

    # Initialize the heap with the start position as (0, 0) and the distance as 0
    heap = [(0, (0, 0))]
    visited = set([(0, 0)])

    while heap:
        current_distance, (x, y) = heapq.heappop(heap)

        # If we have reached the destination, return True
        if current_distance == n:
            return True

        for dx, dy in directions.values():
            nx, ny = x + dx, y + dy

            # Check if the new position is within the bounds and not obstructed
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                visited.add((nx, ny))
                heapq.heappush(heap, (current_distance + 1, (nx, ny)))

    return False

