def solve_robot_path(record):
    directions = {'L': (-1, 0), 'R': (1, 0), 'U': (0, -1), 'D': (0, 1)}
    n, m = len(record), len(record[0])
    visited = [[False] * m for _ in range(n)]
    start_x, start_y = None, None
    path_length = 0

    # Find the starting position of the robot
    for i in range(n):
        for j in range(m):
            if record[i][j] == 'X':
                continue
            start_x, start_y = i, j
            break

    # Check all possible starting positions
    for i in range(n):
        for j in range(m):
            if visited[i][j]:
                continue
            queue = [(i, j, 0)]
            while queue:
                x, y, steps = queue.pop(0)
                if steps > path_length:
                    break
                if record[x][y] != 'X':
                    path_length = max(path_length, steps + 1)
                    visited[x][y] = True
                    for dx, dy in directions.values():
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                            queue.append((nx, ny, steps + 1))

    return "OK" if path_length == len(record) else "BUG"

# Read input
record = input().strip()
# Solve the problem
result = solve_robot_path(record)
# Write the result to stdout
print(result)
